    def find_cycle(tree):
        visited = [False] * (n + 1)
        stack = []
        parent = [-1] * (n + 1)
        for node in range(1, n + 1):
            if not visited[node]:
                current = node
                while current != -1 and not visited[current]:
                    visited[current] = True
                    stack.append(current)
                    next_node = -1
                    for neighbor in tree[current]:
                        if neighbor != parent[current]:
                            next_node = neighbor
                            break
                    parent[current] = next_node
                    current = next_node
                if current != -1:
                    index = stack.index(current)
                    return stack[index:]
        return []

    def dfs(node, parent, tree, depth, max_depth):
        if len(tree[node]) == 1 and node != parent:
            return 1
        max_child_depth = 0
        for neighbor in tree[node]:
            if neighbor != parent:
                child_depth = dfs(neighbor, node, tree, depth, max_depth)
                max_child_depth = max(max_child_depth, child_depth)
        depth[node] = max_child_depth + 1
        max_depth[0] = max(max_depth[0], depth[node])
        return depth[node]

